package com.example.billingservice.service;import com.example.billingservice.model.*;import com.example.billingservice.repository.SubscriptionRepository;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;@Service public class BillingService{private final SubscriptionRepository repo;private final DependencyClient dependencies;public BillingService(SubscriptionRepository r,DependencyClient d){repo=r;dependencies=d;}public Subscription create(CreateSubscriptionRequest q){if(repo.findByOrderId(q.orderId()).isPresent())throw new IllegalStateException("Subscription already exists for this order");Subscription s=new Subscription();s.setOrderId(q.orderId());s.setCustomerId(q.customerId());s.setPlanName(q.planName());s.setMonthlyAmount(q.monthlyAmount());s.setActivationId(q.activationId());s.setFulfillmentId(q.fulfillmentId());s.setStatus(BillingStatus.WAITING_FOR_ACTIVATION);s.setCreatedAt(Instant.now());return repo.save(s);}public List<Subscription>list(){return repo.findAll();}public Subscription byOrder(String id){return repo.findByOrderId(id).orElseThrow(()->new NoSuchElementException("Subscription not found"));}@Scheduled(fixedDelay=5000)public void reconcile(){for(Subscription s:repo.findByStatusIn(List.of(BillingStatus.WAITING_FOR_ACTIVATION,BillingStatus.WAITING_FOR_FULFILLMENT))){String activation=dependencies.activationStatus(s.getOrderId()),fulfillment=dependencies.fulfillmentStatus(s.getOrderId());if(!"ACTIVE".equals(activation))s.setStatus(BillingStatus.WAITING_FOR_ACTIVATION);else if(!"DELIVERED".equals(fulfillment))s.setStatus(BillingStatus.WAITING_FOR_FULFILLMENT);else{Instant now=Instant.now();s.setStatus(BillingStatus.ACTIVE);s.setBillingStartedAt(now);s.setNextBillingAt(now.plus(Duration.ofDays(30)));}repo.save(s);}}}
